import * as E from './engine.js';

export function dailyPanel(s,h){
 const {esc,cost,clock}=h,x=E.specialState(s),d=E.dailyStatus(s),pending=Object.values(x.pending).some(v=>v>0)||x.units.length;
 return '<section class="special-section daily-bonus"><div class="special-heading"><h3>Bono diario</h3><strong>'+x.credits+' cash local</strong></div><p>Vuelve cada día. El quinto premio incluye a General Mike y 2 cash. Calendario de Bogotá; saltar un día reinicia la racha.</p><ol class="daily-track">'+[100,250,500,1000,'Héroe'].map((n,i)=>'<li class="'+(i+1===d.day?'current':'')+'"><small>Día '+(i+1)+'</small><b>'+n+'</b></li>').join('')+'</ol><button class="primary wide" data-action="daily-claim" '+(!d.available?'disabled':'')+'>'+(d.available?'Recoger día '+d.day:'Recogido · próximo en '+clock((d.nextAt-Date.now())/1000))+'</button><small>El cash es una moneda local ganada jugando. Cada meta completada también entrega 1.</small>'+(pending?'<div class="special-reserves"><h4>Recompensas en reserva</h4>'+cost(x.pending)+x.units.map(u=>'<p>'+esc(E.UNITS[u.type].name)+' · esperando plaza</p>').join('')+'<button class="wide" data-action="special-rewards">Recibir lo que quepa</button><small>Los materiales y las tropas sin espacio se conservan.</small></div>':'')+'</section>';
}

export function acquisitionPanel(s,type,h,compact=false){
 const {esc,cost}=h,u=E.UNITS[type],routes=E.acquisitionRoutes(s,type);
 if(compact)return '<p class="acquisition-summary">'+routes.map(r=>esc(r.label)+(r.building?' · '+esc(E.BUILDINGS[r.building].name):'')).join('<br>')+'</p>';
 return '<section class="acquisition-routes"><h3>Cómo conseguir esta tropa</h3><p>Comandante '+E.unlockLevel(type,true)+' · mando '+u.hq+' · '+u.pop+' plazas.</p>'+(routes[0]?.originalLevel&&routes[0].originalLevel!==E.unlockLevel(type,true)?'<small>Nivel del archivo original: '+routes[0].originalLevel+'. Los requisitos de esta partida se adaptan a los diez niveles de mando de Auralis.</small>':'')+routes.map(r=>'<article><b>'+esc(r.label)+'</b>'+(r.building?'<p>'+esc(E.BUILDINGS[r.building].name)+(r.required?' · nivel '+r.required:'')+'</p>':'')+(r.cost?cost(r.cost):'')+(r.message?'<small>'+esc(r.message)+'</small>':'')+(r.kind==='cash'?'<button data-action="requisition" data-type="'+type+'" '+(!E.cashQuote(s,type).ok?'disabled':'')+'>Requisición · '+r.cost.credits+' cash</button><small>'+esc(E.cashQuote(s,type).message)+'</small>':r.building?'<button data-action="special-open" data-type="'+r.building+'">Ver instalación</button>':r.kind==='collection'?'<button data-action="inventory" data-type="collections">Ver colección</button>':r.kind==='daily'?'<button data-action="open-tasks">Ver bono diario</button>':'')+'</article>').join('')+'</section>';
}

export function specialFacilityPanel(s,b,h,selections={}){
 const {img,esc,cost,clock,fmt}=h;
 if(E.isWonder(b.type)){
  const q=E.wonderQuote(s,b),label=q.resource==='credits'?'cash local':({gold:'oro',wood:'madera',supply:'petróleo',metal:'acero'}[q.resource]);
  return '<section class="special-section"><h3>Recogidas de la maravilla</h3><div class="stat-row"><span>Restantes</span><strong>'+q.remaining+' / '+q.charges+'</strong></div><p>'+(q.legacy?'Producción anterior conservada: '+fmt(b.stored)+'.':q.remaining===0?'La maravilla está agotada.':q.ready?'Recogida preparada: '+q.amount+' '+label+'.':'Próxima recogida: '+clock(q.ends===null?q.duration:q.ends-s.time)+'.')+'</p><button class="primary wide" data-action="collect" data-id="'+b.id+'" '+(!q.ok||!q.ready?'disabled':'')+'>Recoger '+(q.legacy?fmt(b.stored):q.amount)+' '+label+'</button>'+(q.remaining===0?cost(q.recharge)+'<button class="wide" data-action="wonder-recharge" data-id="'+b.id+'" '+(!q.ok||!E.affordable(s,q.recharge)?'disabled':'')+'>Restaurar recogidas</button>':'<small>Se consume una carga al recoger el lote completo. Una reserva llena conserva el lote.</small>')+'</section>';
 }
 if(E.isPrototypeCenter(b.type)){
  const q=E.prototypeQuote(s,b.type);
  return '<section class="special-section prototype-project"><h3>Proyecto de prototipo</h3>'+img(q.type,1,true,'special-preview')+'<h4>'+esc(E.UNITS[q.type].name)+'</h4><div class="stat-row"><span>Etapas completadas</span><strong>'+q.step+' / 10</strong></div><div class="progress"><span style="width:'+q.step*10+'%"></span></div>'+(q.job?'<p>Etapa '+(q.step+1)+' en curso · '+clock(q.job.ends-s.time)+'</p>':q.ready?'<p>Prototipo listo. Si no hay plazas, permanece aquí.</p><button class="primary wide" data-action="prototype-claim" data-type="'+b.type+'" '+(!q.canClaim?'disabled':'')+'>Recoger prototipo</button>':cost(q.cost)+'<p>'+clock(q.duration)+' por etapa · '+(s.difficulty==='simulation'?'tiempo de simulación':'acelerado por dificultad')+'</p><button class="primary wide" data-action="prototype-next" data-type="'+b.type+'" '+(!q.ok||!E.affordable(s,q.cost)?'disabled':'')+'>Iniciar etapa '+(q.step+1)+'</button>')+(q.message&&!q.job&&!q.ready?'<small>'+esc(q.message)+'</small>':'')+'<details><summary>Secuencia de proyectos</summary><ol>'+q.sequence.map((type,i)=>'<li class="'+(i===q.index?'current':'')+'">'+esc(E.UNITS[type].name)+' · centro nivel '+(Math.floor(i/2)+1)+'</li>').join('')+'</ol></details></section>';
 }
 if(b.type==='fusion'){
  const j=E.specialState(s).fusions.find(j=>j.building===b.id);
  if(j)return '<section class="special-section fusion-project"><h3>Fusión atómica</h3><div class="fusion-pair">'+j.inputs.map(u=>'<div>'+img(u.type,u.level,true)+'<small>'+esc(E.UNITS[u.type].name)+'</small></div>').join('')+'</div><p>Ambas tropas están protegidas y conservan sus plazas.</p>'+(j.status==='ready'?img(j.type,1,true,'special-preview')+'<h4>'+esc(E.UNITS[j.type].name)+'</h4><button class="primary wide" data-action="fusion-claim" data-id="'+b.id+'" '+(b.hp<=0||!!b.job||E.population(s)>E.populationCap(s)?'disabled':'')+'>Recoger resultado y tropas</button>':'<p>En estudio · '+clock(j.ends-s.time)+'</p><div class="progress"><span style="width:'+Math.max(0,Math.min(100,(s.time-j.started)/(j.ends-j.started)*100))+'%"></span></div>')+(b.hp<=0?'<p>Repara la cámara para continuar. Las tropas se conservan.</p>':'')+'<button class="secondary wide" data-action="fusion-cancel-dialog" data-id="'+b.id+'">Cancelar y recuperar tropas</button></section>';
  const units=s.army.filter(u=>E.fusionEligible(u.type)),ids=selections[b.id]||['',''],q=E.fusionQuote(s,b.id,ids),possible=[...new Set(q.possible)];
  return '<section class="special-section fusion-project"><h3>Fusión atómica</h3><p>Dos tropas participan y regresan junto al resultado. La potencia y el azar determinan la nueva unidad.</p>'+[0,1].map(i=>'<label>Tropa '+(i+1)+'<select data-fusion-building="'+b.id+'" data-fusion-slot="'+i+'" aria-label="Tropa '+(i+1)+' para fusionar"><option value="">Seleccionar tropa</option>'+units.map(u=>'<option value="'+u.id+'" '+(ids[i]===u.id?'selected':'')+'>'+esc(E.UNITS[u.type].name)+' · '+u.id+' · potencia '+E.fusionPower(u.type)+'</option>').join('')+'</select></label>').join('')+cost(q.cost)+(q.ok?'<p>'+clock(q.duration)+' · resultados posibles:</p><p>'+possible.map(t=>esc(E.UNITS[t].name)).join(', ')+'</p>':'<small>'+esc(q.message)+'</small>')+'<button class="primary wide" data-action="fusion-start" data-id="'+b.id+'" '+(!q.ok||!E.affordable(s,q.cost)?'disabled':'')+'>Iniciar fusión</button><small>Al cancelar recuperas ambas tropas; los materiales empleados no se devuelven.</small></section>';
 }
 return '';
}

export function specialOverview(s,h){
 const {head,esc,img}=h;
 return head('CREACIÓN Y OBTENCIÓN','Prototipos, fusión y maravillas')+'<p>Los proyectos especiales tienen sus propias colas. Selecciona una instalación para gestionar sus etapas, tropas o recogidas.</p><div class="special-overview">'+['robotics','swb139','fusion',...Object.keys(E.BUILDINGS).filter(E.isWonder)].map(type=>{const b=s.buildings.find(b=>b.type===type);return '<article>'+img(type)+'<h3>'+esc(E.BUILDINGS[type].name)+'</h3><p>'+esc(E.BUILDINGS[type].description)+'</p><button data-action="special-open" data-type="'+type+'">'+(b?'Ver en mi base':'Ver plano y requisitos')+'</button></article>';}).join('')+'</div>';
}
